return [
  {
    json: {
      reportId: 'sample-stable-week',
      period: 'Fictional week A',
      websiteVisits: 320,
      automationRequests: 18,
      completedRequests: 16,
      overdueItems: 0,
      criticalExceptions: 0,
      owner: 'Operations lead',
      note: 'Synthetic data for workflow testing only'
    }
  },
  {
    json: {
      reportId: 'sample-review-week',
      period: 'Fictional week B',
      websiteVisits: 280,
      automationRequests: 22,
      completedRequests: 12,
      overdueItems: 2,
      criticalExceptions: 1,
      owner: '',
      note: 'Synthetic data for workflow testing only'
    }
  }
];

return $input.all().map((item) => {
  const source = item.json;
  const visits = Math.max(0, Number(source.websiteVisits) || 0);
  const requests = Math.max(0, Number(source.automationRequests) || 0);
  const completed = Math.max(0, Number(source.completedRequests) || 0);
  const overdue = Math.max(0, Number(source.overdueItems) || 0);
  const critical = Math.max(0, Number(source.criticalExceptions) || 0);
  const owner = String(source.owner || '').trim();
  const reviewReasons = [];

  if (!owner) reviewReasons.push('Assign a report owner');
  if (critical > 0) reviewReasons.push(`Review ${critical} critical exception${critical === 1 ? '' : 's'}`);
  if (overdue > 0) reviewReasons.push(`Review ${overdue} overdue item${overdue === 1 ? '' : 's'}`);
  if (completed > requests) reviewReasons.push('Completed requests exceed received requests');

  const requestRatePercent = visits > 0 ? Number(((requests / visits) * 100).toFixed(1)) : null;
  const completionRatePercent = requests > 0 ? Number(((completed / requests) * 100).toFixed(1)) : null;
  const requiresHumanReview = reviewReasons.length > 0;

  return {
    json: {
      reportId: String(source.reportId || ''),
      period: String(source.period || ''),
      websiteVisits: visits,
      automationRequests: requests,
      completedRequests: completed,
      requestRatePercent,
      completionRatePercent,
      overdueItems: overdue,
      criticalExceptions: critical,
      owner,
      reviewReasons,
      requiresHumanReview,
      note: String(source.note || '')
    }
  };
});
